import { Injectable } from '@angular/core';
import { CaseDetailResponce } from '../../adminpanel/interfaces/casebuilder.interface';
import { HttpClient, HttpParams } from '@angular/common/http';
import { BehaviorSubject, firstValueFrom } from 'rxjs';
import { environment } from '../../../environments/environment';
import { notification } from '../interfaces/notification.interface';

@Injectable({
  providedIn: 'root'
})
export class NotificationsService {
  private CaseDetail: CaseDetailResponce;

  _isNotification = new BehaviorSubject<boolean>(false);
  isNotification$ = this._isNotification.asObservable();

  /**
   * Client-only notifications that don't have a backend record (e.g. "Final
   * transcript published" posted from the publish socket event). Merged with
   * the server list inside <notifications>; ids are prefixed `client-` so
   * remove/clear paths can distinguish them and skip the API call.
   */
  private _clientNotifications = new BehaviorSubject<notification[]>([]);
  clientNotifications$ = this._clientNotifications.asObservable();

  // isNotification: boolean = false;
  constructor(private http: HttpClient) { }

  addClientNotification(n: notification): void {
    const list = this._clientNotifications.getValue();
    if (n.nNTid && list.some(x => x.nNTid === n.nNTid)) return;
    this._clientNotifications.next([n, ...list]);
    this._isNotification.next(true);
  }

  removeClientNotification(nNTid: string): void {
    const list = this._clientNotifications.getValue();
    this._clientNotifications.next(list.filter(x => x.nNTid !== nNTid));
  }

  clearClientNotifications(): void {
    this._clientNotifications.next([]);
  }


  async getNotifcationList(nCaseid: string): Promise<any> {
    try {
      var params = new HttpParams().set('nCaseid', nCaseid);
      const res: any = await firstValueFrom(
        this.http.get<any[]>(
          `${environment.cloudUrl}${environment.coreservice}/case/notifications`,
          { params: params }
        )
      );
      if (res.length && res.filter(e => !e.bIsseen).length) {
        console.log('isNotification', true)
        this._isNotification.next(true)
      } else {
        this._isNotification.next(false)
      }
      return res;
    } catch (err) {
      return {};
    }
  }




  async deleteNotification(nCaseid: string, nNTid?: number): Promise<any> {

    try {
      const res: any = await firstValueFrom(
        this.http.post(
          `${environment.cloudUrl}${environment.coreservice}/case/notification/delete`,
          { nNTid: nNTid || null, nCaseid: nCaseid }
        )
      );
      return res;
    } catch (err) {
      return {};
    }
  }



  async syncNotifcation(nCaseid: string): Promise<any> {
    try {
      var params = new HttpParams().set('nCaseid', nCaseid);
      const res: any = await firstValueFrom(
        this.http.get<any[]>(
          `${environment.cloudUrl}${environment.coreservice}/case/syncnotifications`,
          { params: params }
        )
      );
      this._isNotification.next(false);
      return res;
    } catch (err) {
      return {};
    }
  }




}
